import { safeHtml } from '../platform/html.js'
import { getChipUsage, getDatabaseSummary, getEliteClubExposure, getEliteFormations, getElitePlayerStats, getEliteTransfers, getFixtures, getPlayerProfiles } from '../services/database.js'
import { ELITE_COHORTS, eliteNumericSort, formatEliteMetric, getAvailableLockedEliteRounds, selectEliteView } from '../services/eliteManagerIntelligence.js'
import { buildAnalysis } from '../services/analysisEngine.js'
import { getIntelligenceRound, getIntelligenceRounds } from '../services/intelligenceHelpers.js'
import { getPlayerDetailProfile, renderPlayerDetailProfile } from './players.js'
import { clubLogo, esc, fmt, opportunityMatrix, playerLine, playerPhoto, positionLabel, scoreBar } from './intelligenceUi.js'
import { filterEliteLineupRows } from '../services/historyPresentation.js'

const tabs = [['overview','Overzicht'],['topmanagers','Topmanagers'],['clubs','Clubs'],['players','Spelers'],['market','Kopen & verkopen'],['fixtures','Speelschema'],['opponents','Tegenstanders'],['budget','Budget'],['positions','Posities'],['trends','Trends'],['radar','Onder de radar'],['overvalued','Overgewaardeerd'],['broadcast','Uitzending']]
const state = { season:'', round:0, horizon:3, cohort:100, tab:'overview', eliteView:'market', eliteRound:null, eliteSort:'selectedPct', eliteDirection:'desc', eliteSearch:'', eliteClub:'', playerId:'', insightId:'', playerTab:'overview', radarExpanded:false }
function ensure(){ const summary=getDatabaseSummary(); state.season ||= summary.activeSeason || getPlayerProfiles()[0]?.season || ''; const rounds=getIntelligenceRounds(state.season); if(!rounds.includes(Number(state.round))) state.round=getIntelligenceRound(state.season); return rounds }
const metric = (label,value) => `<span><small>${label}</small><b>${value}</b></span>`
const metricLabels={previous5:'Vorige 5',next5:'Komende 5',following5:'Daarna 5',swing:'Verschil',sample:'Steekproef',qualityPercentile:'Niveau verwachte punten',ownershipPercentile:'Niveau populariteit',fixture:'Schema',vorm:'Vorm',gekozen:'Gekozen',prijs:'Prijs',start:'Startspeelronde',before:'Voor omslag',after:'Na omslag',puntenPer90:'Punten per 90'}
const visibleMetrics=metrics=>Object.entries(metrics??{}).filter(([,value])=>value!==null&&value!==undefined&&value!=='')
const naturalCopy=value=>String(value??'').replace(/Projectiepercentiel ([\d,.]+) tegenover ownershippercentiel ([\d,.]+)\.?/gi,'Zijn verwachte punten horen duidelijk hoger in de markt dan zijn populariteit.').replace(/ownershippercentiel/gi,'populariteitsniveau').replace(/projectiepercentiel/gi,'niveau van verwachte punten').replace(/market[- ]?mismatch/gi,'verschil tussen verwachte prestaties en populariteit').replace(/fixture(s)?/gi,'wedstrijd$1').replace(/confidence/gi,'zekerheid').replace(/canonical/gi,'geldige').replace(/buy window/gi,'koopmoment').replace(/sample/gi,'steekproef')
const labels={ 'UNDER THE RADAR':'Onder de radar','OWNERSHIP GAP':'Populariteitskloof','OWNERSHIP TRAP':'Populariteitsval','MINUTES BREAKOUT':'Minuten stijgen','MINUTES DECLINE':'Minuten dalen','VALUE EMERGING':'Prijsvoordeel','FIXTURE SWING +':'Schema wordt beter','FIXTURE SWING -':'Schema wordt zwaarder','GREEN RUN':'Gunstige reeks','GREEN RUN START':'Start gunstige reeks','SCHEDULE CLIFF':'Omslag naar zwaar schema','UPCOMING SWING +':'Komend beter schema','UPCOMING SWING -':'Komend zwaarder schema','STAT OF THE WEEK':'Statistiek van de week' }
const info=(label,copy)=>{const expanded=label==='Kansenmatrix'?'X-as: gekozen percentage; links weinig gekozen, rechts veel gekozen.\nY-as: verwachte Fantasy-punten; boven betekent meer verwacht.\nLinksboven is interessant onder de radar; rechtsboven zijn populaire toppers. Linksonder heeft lage prioriteit; rechtsonder kan overgewaardeerd zijn.\nGroen is een gunstig, geel een gemiddeld en oranje/rood een lastig schema. Cirkelgrootte is spelersprijs.\nDe stippellijnen zijn de medianen van de getoonde spelers en verdelen de markt in vier groepen.':copy;return `<span class="player-column-tooltip intel-info-wrap" tabindex="0" role="button" aria-label="Uitleg over ${esc(label)}"><span class="player-column-tooltip-icon" aria-hidden="true">i</span><span class="player-column-tooltip-content" role="tooltip"><strong>${esc(label)}</strong>${String(expanded).split('\n').map(line=>`<span>${esc(line)}</span>`).join('')}</span></span>`}
function insightCard(i, compact=false){ if(!i)return '<div class="intel-empty">Onvoldoende betrouwbare data voor een sterke conclusie.</div>'; return `<article class="talking-card ${i.polarity}" data-intel-insight="${esc(i.id)}"><header><span>${esc(labels[i.category]||i.category)}</span><b>${fmt(i.talkingPointScore,0)}</b></header><h3>${esc(naturalCopy(i.title))}</h3><p>${esc(naturalCopy(i.conclusion))}</p>${compact?'':`<div class="talking-evidence">${visibleMetrics(i.metrics).slice(0,6).map(([k,v])=>metric(metricLabels[k]||k,fmt(v))).join('')}</div><footer><span>Zekerheid ${esc(i.confidence.level)}</span><button>Bekijk onderbouwing</button></footer>`}</article>` }
function executiveCard(icon,label,item){ const isClub=item?.club && !item?.title; const title=isClub?item.club:item?.title; const value=isClub?`${fmt(item.score,0)}/100`:item?.conclusion; return `<article class="executive-card"><span>${icon} ${label}</span><h3>${esc(title||'Nog geen sterk signaal')}</h3><p>${esc(value||'Onvoldoende betrouwbare data.')}</p></article>` }
function overview(a){ const e=a.executive; return `<section class="intel-hero panel"><div><span class="eyebrow">FVT Intelligence</span><h2>De markt, eerder gezien</h2><p>Speelronde ${a.startRound} · vooruitblik ${a.horizon} ronde${a.horizon===1?'':'s'}</p></div><div class="intel-live">${metric('Sterke signalen',a.stats.strongInsights)}${metric('Onder de radar',a.stats.underRadar)}${metric('Schema-omslagen',a.stats.fixtureSwings)}${metric('Minutenalerts',a.stats.minutesAlerts)}${metric('Hoge zekerheid',a.stats.highConfidence)}</div></section><section class="executive-grid">${executiveCard('🔥','Beste ontwikkeling',e.development)}${executiveCard('📉','Grootste terugval',e.decline)}${executiveCard('🟢','Club om te volgen',e.hotClub)}${executiveCard('🔴','Voorzichtig bij',e.coldClub)}${executiveCard('💰','Beste budgetkans',e.budget&&{title:e.budget.name,conclusion:`${fmt(e.budget.expectedPoints)} xP · € ${fmt(e.budget.price)} mln`})}${executiveCard('👀','Meest onderschat',e.underrated)}</section><section class="intel-grid two"><div class="panel"><span class="eyebrow">Belangrijkste conclusies</span><div class="talking-list">${a.overviewInsights.slice(0,5).map(i=>insightCard(i)).join('')||'<div class="intel-empty">Nog geen signalen boven de kwaliteitsgrens.</div>'}</div></div><div class="panel"><span class="eyebrow">Marktbrede aandachtspunten</span><h3>Wat kan de markt hiermee?</h3><div class="action-list">${a.actions.map(x=>`<article class="${x.level}"><b>${x.level}</b><p>${esc(x.insight.fantasy)}</p><small>${esc(x.insight.title)}</small></article>`).join('')||'<div class="intel-empty">Nog geen betrouwbare acties.</div>'}</div></div></section><section class="panel"><span class="eyebrow">Kansenmatrix ${info('Kansenmatrix','Horizontaal: populariteit. Verticaal: verwachte punten. Cirkelgrootte: prijs. Kleur: kwaliteit van het komende schema. De stippellijnen zijn marktmedianen.')}</span><h3>Projectie tegenover populariteit</h3>${opportunityMatrix(a.matrix)}</section><section class="panel"><span class="eyebrow">Marktstructuur</span><h3>Waar zit het voordeel?</h3><div class="edge-list">${a.edgeAreas.map((x,i)=>`<span><b>${i+1}</b><span><strong>${esc(x.title)}</strong><small>${esc(x.conclusion)} ${esc(x.evidence)}</small></span></span>`).join('')}</div></section>` }
function clubs(a){const tip={total:'Samengestelde FVT-clubscore van 0–100.\nAanval, verdediging, schema, vorm en prijswaarde tellen mee.\n50 is ongeveer middenmoot; hoger is een aantrekkelijker Fantasy-profiel.\nDit voorspelt niet de eindstand.',attack:'Aantrekkelijkheid van de aanvallende Fantasy-opties.\nVerwachte punten, vorm, speelzekerheid en prijswaarde tellen mee.\n50 is ongeveer gemiddeld; hoger is beter.',defence:'Fantasy-potentie van doelmannen en verdedigers.\nVerwachte punten, vorm, speelzekerheid en prijswaarde tellen mee.\n50 is ongeveer gemiddeld; hoger is beter.',fixture:'Kwaliteit van de komende wedstrijden in de gekozen periode.\nHoger betekent een gunstiger schema.\nEen vrije ronde telt niet als nul; dubbele speelrondes tellen volledig mee.',value:'Gemiddelde verwachte Fantasy-punten per miljoen spelersprijs.\nDit is geen 0–100-score. Een hogere waarde betekent meer verwachte punten voor hetzelfde budget.\nxP = verwachte Fantasy-punten over de gekozen periode.',unused:'Meet hoeveel populariteitsruimte er nog is.\nHoger betekent dat spelers van deze club gemiddeld weinig worden gekozen.\nDe score zegt niet dat de club populairder is.'};return `<section class="intel-grid three"><article class="panel"><span class="eyebrow">Sterkste clubs ${info('Clubscore',tip.total)}</span>${a.clubs.slice(0,5).map(c=>`<div class="club-rank"><b>${c.rank}</b>${clubLogo(c.club)}<span>${esc(c.club)}<small>Schema ${fmt(c.fixture,0)} · xP ${fmt(c.projectedPoints)}</small></span><strong>${fmt(c.score,0)}</strong></div>`).join('')}</article><article class="panel"><span class="eyebrow">Zwakste clubs</span>${a.clubs.slice(-5).reverse().map(c=>`<div class="club-rank">${clubLogo(c.club)}<span>${esc(c.club)}<small>Vorm ${fmt(c.form,0)}</small></span><strong>${fmt(c.score,0)}</strong></div>`).join('')}</article><article class="panel"><span class="eyebrow">Weinig gekozen clubs ${info('Onbenut potentieel',tip.unused)}</span>${[...a.clubs].sort((x,y)=>y.ownershipOpportunity-x.ownershipOpportunity).slice(0,5).map(c=>`<div class="club-rank">${clubLogo(c.club)}<span>${esc(c.club)}<small>Gemiddeld gekozen ${fmt(c.ownership)}%</small></span><strong>${fmt(c.ownershipOpportunity,0)}</strong></div>`).join('')}</article></section><section class="panel intel-table"><h3>Clubranglijst</h3><table><thead><tr><th>#</th><th>Club</th><th>Totaal ${info('Totaalscore',tip.total)}</th><th>Aanval ${info('Aanval',tip.attack)}</th><th>Verdediging ${info('Verdediging',tip.defence)}</th><th>Schema ${info('Schema',tip.fixture)}</th><th>Prijswaarde ${info('Prijswaarde',tip.value)}</th><th>Onbenut potentieel ${info('Onbenut potentieel',tip.unused)}</th></tr></thead><tbody>${a.clubs.map(c=>`<tr><td>${c.rank}</td><td>${clubLogo(c.club)} ${esc(c.club)}</td><td><b>${fmt(c.score,0)}</b>${scoreBar(c.score)}</td><td>${fmt(c.attack,0)}</td><td>${fmt(c.defence,0)}</td><td>${fmt(c.fixture,0)}</td><td>${fmt(c.value,2)}</td><td>${fmt(c.ownershipOpportunity,0)}</td></tr>`).join('')}</tbody></table></section>`}
function players(a){const rising=a.playerMovers.filter(x=>x.score>0).slice(0,8),falling=a.playerMovers.filter(x=>x.score<0).slice(0,8),minutes=a.minutesSignals;const rich=x=>{const p=x.player,s=x.signals[0];return `<button class="intel-player-line" data-intel-player="${esc(p.id)}"><span>${playerPhoto(p,'intel-mini-photo')}<span><strong>${esc(p.name)}</strong><small>${esc(s.label)} · ${fmt(s.previous)} → ${fmt(s.current)} · ${fmt(p.expectedPoints)} xP</small></span></span><b title="Sterkte van de gemeten verandering; geen kanspercentage">${x.score>0?'+':''}${fmt(x.score,0)}</b></button>`};const role=s=>`<button class="intel-player-line" data-intel-player="${esc(s.player.id)}"><span>${playerPhoto(s.player,'intel-mini-photo')}<span><strong>${esc(s.player.name)}</strong><small>${esc(s.source)} · zekerheid ${esc(s.confidence.level)}</small></span></span><b>${s.delta>0?'+':''}${fmt(s.delta,0)}</b></button>`;return `<section class="intel-grid three"><article class="panel"><span class="eyebrow">Stijgers ${info('Stijgers','Spelers van wie het Fantasy-profiel sinds de vorige ronde aantoonbaar is verbeterd.\nVeranderingen in verwachte punten, minuten of populariteit kunnen meetellen.\nDe score rechts is de sterkte van de verandering op een vergelijkingsschaal; het is geen kanspercentage.')}</span>${rising.map(rich).join('')||'<div class="intel-empty">Geen aantoonbare stijgers.</div>'}</article><article class="panel"><span class="eyebrow">Dalers ${info('Dalers','Spelers van wie het Fantasy-profiel sinds de vorige ronde aantoonbaar is verslechterd.\nEen speler die op nul stond en op nul blijft, telt niet mee.\nDe score rechts toont de sterkte van de verandering, niet de huidige spelerskwaliteit.')}</span>${falling.map(rich).join('')||'<div class="intel-empty">Geen aantoonbare dalers.</div>'}</article><article class="panel"><span class="eyebrow">Minutenontwikkeling ${info('Minutenontwikkeling','Betekenisvolle veranderingen in gespeelde of verwachte minuten.\nBij één of twee gespeelde rondes kan een duidelijk signaal al verschijnen met lagere zekerheid.\nMaximaal vijf stijgende en vijf dalende signalen.')}</span>${minutes.map(role).join('')||'<div class="intel-empty">Geen betekenisvolle minutenverandering gevonden.</div>'}</article></section>`}
function market(a){const groups=a.actionGroups||{},sections=[['Nu kopen',groups.buy,'Sterke combinatie van verwachte punten, speelminuten, schema, vorm en prijs. De signalen zijn sterk genoeg voor een duidelijk positief oordeel.','buyScore'],['Overwegen',groups.consider,'Positief profiel, maar één of meer onderdelen zijn nog niet overtuigend genoeg.','buyScore'],['Houden',groups.hold,'Goede bestaande kwaliteit, maar onvoldoende extra voordeel om hem nu specifiek als koopkans aan te merken.','trajectoryScore'],['Verkoop overwegen',groups.sell,'Het huidige of toekomstige profiel is zwakker door bijvoorbeeld lagere verwachte punten, minutenrisico, schema of matige waarde.','cautionScore']];return `<section class="decision-grid">${sections.map(([title,list=[],copy,score])=>`<article class="panel"><span class="eyebrow">${title} ${info(title,`${copy}\nDe score loopt van 0–100; hoger betekent een sterker signaal binnen deze categorie.\nEen score van 85 betekent niet 85% kans.`)}</span><p>${copy}</p>${[...list].sort((x,y)=>y[score]-x[score]).slice(0,8).map(p=>playerLine(p,score)).join('')||'<div class="intel-empty">Geen overtuigende kandidaten.</div>'}</article>`).join('')}</section>`}
function fixtures(a){ const sorted=[...a.clubs].sort((x,y)=>y.fixture-x.fixture), swings=a.structuralFixtures.filter(x=>x.structuralSwing!==null), upcoming=a.structuralFixtures.flatMap(c=>(c.upcomingSwings||[]).map(s=>({...s,club:c.club}))).sort((x,y)=>y.relevance-x.relevance), greens=a.structuralFixtures.filter(c=>c.greenRun||c.upcomingGreenRunStart), cliffs=a.structuralFixtures.filter(c=>c.scheduleCliff), swingRows=list=>list.slice(0,4).map(c=>`<div class="fixture-rank" title="Vorige: ${fmt(c.previousAverage,0)} · Komende: ${fmt(c.nextAverage,0)} · Sample ${esc(c.sample)}"><span>${clubLogo(c.club)} ${esc(c.club)}</span><small>${fmt(c.previousAverage,0)} → ${fmt(c.nextAverage,0)} · ${esc(c.confidence.level)}</small><b class="${c.structuralSwing>=0?'up':'down'}">${c.structuralSwing>=0?'+':''}${fmt(c.structuralSwing,0)}</b></div>`).join(''), futureSections=`${upcoming.length?`<article class="panel"><span class="eyebrow">Toekomstige omslagpunten</span>${upcoming.slice(0,6).map(c=>`<div class="fixture-rank"><span>${clubLogo(c.club)} ${esc(c.club)}<small>Vanaf SR${c.startRound} · ${fmt(c.beforeAverage,0)} → ${fmt(c.afterAverage,0)} · ${esc(c.confidence.level)}</small></span><b class="${c.delta>0?'up':'down'}">${c.delta>0?'+':''}${fmt(c.delta,0)}</b></div>`).join('')}</article>`:''}${greens.length?`<article class="panel"><span class="eyebrow">Green Runs · komende 5</span>${greens.slice(0,6).map(c=>`<div class="fixture-rank"><span>${clubLogo(c.club)} ${esc(c.club)}<small>${c.greenRun?`Actief · gem. ${fmt(c.nextAverage,0)}`:`Start SR${c.upcomingGreenRunStart.startRound} · gem. ${fmt(c.upcomingGreenRunStart.average,0)}`}</small></span><b class="up">${c.greenRun?'RUN':'START'}</b></div>`).join('')}</article>`:''}${cliffs.length?`<article class="panel"><span class="eyebrow">Schedule Cliffs · komende 5 vs daarna 5</span>${cliffs.slice(0,6).map(c=>`<div class="fixture-rank"><span>${clubLogo(c.club)} ${esc(c.club)}<small>${fmt(c.nextAverage,0)} → ${fmt(c.followingAverage,0)}</small></span><b class="down">${fmt(c.scheduleCliffDelta,0)}</b></div>`).join('')}</article>`:''}`; return `<section class="intel-grid two"><article class="panel"><span class="eyebrow">Beste schema’s · horizon ${a.horizon}</span>${sorted.slice(0,8).map(c=>`<div class="fixture-rank">${clubLogo(c.club)}<span>${esc(c.club)}</span>${scoreBar(c.fixture)}<b>${fmt(c.fixture,0)}</b></div>`).join('')}</article><article class="panel"><span class="eyebrow">Current structural swing · vorige 5 vs komende 5</span><h4>Positieve fixture swings</h4>${swingRows(swings.filter(c=>c.structuralSwing>0))||'<div class="intel-empty">Geen geldige positieve swing.</div>'}<h4>Negatieve fixture swings</h4>${swingRows(swings.filter(c=>c.structuralSwing<0))||'<div class="intel-empty">Geen geldige negatieve swing.</div>'}</article></section>${futureSections?`<section class="intel-grid two">${futureSections}</section>`:''}<section class="panel intel-heatmap"><span class="eyebrow">Intelligence heatmap</span><h3>Club × speelronde</h3><div class="heatmap-grid" style="--heat-cols:${a.horizon}">${a.clubs.slice(0,18).map(c=>`<strong>${clubLogo(c.club)} ${esc(c.club)}</strong>${Array.from({length:a.horizon},(_,i)=>{const report=c.assets[0]?.fixture?.rounds?.find(r=>Number(r.round)===a.startRound+i);const valid=report&&Number.isFinite(Number(report.score))&&report.type!=='blank';return valid?`<span style="--heat:${Number(report.score)}" title="SR${a.startRound+i}: ${fmt(Number(report.score)*10,0)}">${fmt(Number(report.score)*10,0)}</span>`:`<span class="is-missing" title="SR${a.startRound+i}: geen geldige fixturedata">—</span>`}).join('')}`).join('')}</div></section>` }
function opponents(a){const positions=['keeper','verdediger','middenvelder','aanvaller'],top=pos=>[...a.opponentStats].filter(o=>o.positions[pos].pointsPer90!==null).sort((x,y)=>y.positions[pos].pointsPer90-x.positions[pos].pointsPer90||y.positions[pos].matches-x.positions[pos].matches).slice(0,3),explanation='Dit toont hoeveel Fantasy-punten spelers tégen een club behaalden.\nPunten worden omgerekend naar 90 minuten; hoger betekent historisch meer toegestane punten.\nPosities worden apart beoordeeld. Eén waarneming geeft lage, 2–4 middelhoge en 5+ hoge zekerheid.\nOntbrekende minuten of punten worden uitgesloten; extreem korte speelduur telt alleen mee wanneer die geldig is.';return `<section class="intel-grid four opponent-top">${positions.map(pos=>`<article class="panel"><span class="eyebrow">Top 3 · ${positionLabel(pos)}</span>${top(pos).map(o=>{const d=o.positions[pos];return `<div class="club-rank" title="${d.matches} waarneming(en) · zekerheid ${d.confidence}">${clubLogo(o.opponent)}<span>${esc(o.opponent)}<small>${d.matches} waarneming(en) · ${esc(d.confidence)}</small></span><b>${fmt(d.pointsPer90)}</b></div>`}).join('')||'<div class="intel-empty">Nog geen geldige waarnemingen.</div>'}</article>`).join('')}</section><section class="panel intel-table"><span class="eyebrow">Toegestane punten per 90 ${info('Tegenstanderdata',explanation)}</span><h3>Tegen welke clubs worden de meeste fantasypunten gehaald?</h3><table><thead><tr><th>#</th><th>Tegenstander</th><th>Waarnemingen</th><th>Punten/90</th>${positions.map(p=>`<th>${positionLabel(p)}</th>`).join('')}<th>Zekerheid</th></tr></thead><tbody>${a.opponentStats.map((o,i)=>`<tr><td>${i+1}</td><td>${clubLogo(o.opponent)} ${esc(o.opponent)}</td><td>${o.matches}</td><td><b>${fmt(o.pointsPer90)}</b></td>${positions.map(p=>{const d=o.positions[p],copy=d.pointsPer90===null?d.missingReason:`${fmt(d.pointsPer90)} punten per 90 · ${d.matches} waarneming(en) · zekerheid ${d.confidence}`;return `<td title="${esc(copy)}">${fmt(d.pointsPer90)}${d.pointsPer90===null?'':` <small>${esc(d.confidence)}</small>`}</td>`}).join('')}<td><span class="confidence ${o.confidence}">${o.confidence}</span></td></tr>`).join('')}</tbody></table>${a.opponentStats.length?'':'<div class="intel-empty">Nog geen geldige wedstrijdhistorie voor deze analyse.</div>'}</section>`}
function budget(a){const ranges=[4,6,8,10,12],cell=(p,from)=>{const b=p.bands.find(x=>x.from===from);return b?(b.players<2?`<span title="Kleine steekproef">${b.players} speler · ${fmt(b.averageXp)} xP · lage zekerheid</span>`:`<span>${b.players} spelers · ${fmt(b.averageXp)} xP · ${fmt(b.value,2)} xP/mln</span>`):'<span>Te weinig spelers</span>'};return `<section class="intel-grid two"><article class="panel intel-table"><span class="eyebrow">Prijsverloop ${info('Prijsverloop','Alleen spelers met een wedstrijd en minimaal 45 verwachte minuten tellen mee.\nPer prijsvak zie je gemiddelde verwachte punten en punten per miljoen.\nxP = verwachte Fantasy-punten over de gekozen periode.')}</span><h3>Verwachte opbrengst per prijsklasse</h3><table><thead><tr><th>Prijs</th><th>Spelers</th><th>Gem. xP</th><th>xP/mln</th></tr></thead><tbody>${a.budget.bands.map(b=>`<tr><td>${b.band}</td><td>${b.players}</td><td>${fmt(b.averageXp)}</td><td>${fmt(b.value,2)}</td></tr>`).join('')}</tbody></table></article><article class="panel"><span class="eyebrow">Beste prijsklasse per positie</span>${a.positions.map(p=>`<div class="budget-position"><b>${positionLabel(p.position)}</b><strong>${p.sweetSpot}</strong><small>${esc(p.conclusion)}</small></div>`).join('')}</article></section><section class="panel intel-table"><span class="eyebrow">Positie × prijsklasse ${info('Positie en prijsklasse','Vergelijkt binnen iedere linie wat extra budget gemiddeld oplevert.\nCellen met één speler hebben lage zekerheid en leveren geen stevige conclusie op.')}</span><table class="budget-matrix"><thead><tr><th>Positie</th>${ranges.map(from=>`<th>€ ${from}–${from+2} mln</th>`).join('')}</tr></thead><tbody>${a.positions.map(p=>`<tr><th>${positionLabel(p.position)}</th>${ranges.map(from=>`<td>${cell(p,from)}</td>`).join('')}</tr>`).join('')}</tbody></table></section><section class="panel"><span class="eyebrow">Vergelijking met goedkoper alternatief ${info('Meerprijs','Vergelijkt een dure speler met een goedkopere speler op dezelfde positie die minimaal 85% van zijn verwachte punten haalt.')}</span><div class="premium-grid">${a.budget.premiumTax.slice(0,6).map(x=>`<article><b>${esc(x.premium.name)}</b><span>tegenover ${esc(x.alternative.name)}</span><strong>€ ${fmt(x.priceDifference)} mln duurder · ${fmt(Math.abs(x.xpDifference))} xP ${x.xpDifference>=0?'extra':'minder'}</strong></article>`).join('')||'<div class="intel-empty">Geen betrouwbare premiumvergelijking.</div>'}</div></section>`}
function positions(a){const invest=[...a.positions].sort((x,y)=>y.spread-x.spread)[0],save=[...a.positions].sort((x,y)=>x.spread-y.spread)[0];return `<section class="panel position-summary"><span class="eyebrow">Conclusie voor teamopbouw</span><p>Extra kwaliteit levert op basis van de huidige markt vooral bij <b>${positionLabel(invest?.position).toLowerCase()}</b> verschil op. Bij <b>${positionLabel(save?.position).toLowerCase()}</b> liggen top en gemiddelde dichter bij elkaar, waardoor besparen relatief minder xP kost.</p></section><section class="position-grid">${a.positions.map(p=>`<article class="panel"><span class="eyebrow">${positionLabel(p.position)}</span><strong class="position-score">${fmt(p.value,2)}</strong><small>xP per miljoen</small>${scoreBar(p.reliability,'Databetrouwbaarheid')}<div>${metric('Gem. prijs',`€ ${fmt(p.averagePrice)} mln`)}${metric('Gem. xP',fmt(p.averageXp))}${metric('Beste xP',fmt(p.topXp))}${metric('Bruikbare opties',p.usefulOptions)}${metric('Gem. gekozen',`${fmt(p.ownership)}%`)}${metric('Top vs gem.',`+${fmt(p.spread)} xP`)}</div><p>${esc(p.lineupConclusion)}</p></article>`).join('')}</section>`}
function trends(a){return `<section class="panel"><span class="eyebrow">Sinds de vorige ronde ${info('Trends','Alleen aantoonbare veranderingen in populariteit, verwachte punten of minuten.\nSterkte, zekerheid en mogelijke Fantasy-impact bepalen de volgorde.\nMaximaal twaalf signalen; algemene toekomstkwaliteit telt hier niet als trend.')}</span><h3>Wat is werkelijk veranderd?</h3><div class="trend-list">${a.trends.map(t=>`<button class="intel-player-line" data-intel-player="${esc(t.player.id)}"><span>${playerPhoto(t.player,'intel-mini-photo')}<span><strong>${esc(t.player.name)}</strong><small>${esc(t.label)} · ${fmt(t.previous)} → ${fmt(t.current)} · zekerheid ${esc(t.confidence?.level||'laag')}</small></span></span><b class="${t.delta>=0?'up':'down'}">${t.delta>0?'+':''}${fmt(t.delta)}</b></button>`).join('')||'<div class="intel-empty">Sinds de vorige ronde is geen verandering sterk genoeg én met geldige vergelijkingsdata onderbouwd.</div>'}</div></section>`}
function radar(a){const list=state.radarExpanded?a.underRadar:a.underRadar.slice(0,12);return `<section class="panel"><span class="eyebrow">Positieve kansen met lage populariteit ${info('Onder de radar','Spelers die relatief weinig worden gekozen, maar interessant genoeg zijn op basis van verwachte punten, speelminuten, schema en prijs.\nLage populariteit alleen is nooit voldoende.\nDe score loopt van 0–100; hoger betekent een sterker totaalprofiel.')}</span><div class="radar-grid">${list.map(p=>`<button class="intel-player-line" data-intel-player="${esc(p.id)}"><span>${playerPhoto(p,'intel-mini-photo')}<span><strong>${esc(p.name)}</strong><small>${esc(p.club)} · ${fmt(p.expectedPoints)} xP · ${fmt(p.expectedMinutes,0)} min · ${fmt(p.ownership)}% gekozen</small></span></span><b>${fmt(p.underRadarScore,0)}</b></button>`).join('')||'<div class="intel-empty">Geen speler voldoet aan alle positieve kwaliteitsgrenzen.</div>'}</div>${a.underRadar.length>12?`<button class="intel-show-more" data-radar-toggle>${state.radarExpanded?'Toon minder':`Toon alle ${a.underRadar.length}`}</button>`:''}</section>`}
function overvalued(a){return `<section class="panel"><span class="eyebrow">Mogelijk overgewaardeerd ${info('Overwaarderingsrisico','Deze score combineert hoge populariteit en prijs met relatief lage verwachte punten, minuten, schema en waarde.\nHoger betekent een groter risico dat de markt meer betaalt of kiest dan de vooruitzichten rechtvaardigen.\nDe schaal loopt van 0–100 en is geen automatisch verkoopadvies.')}</span><div class="radar-grid">${a.overvalued.map(x=>`<article class="overvalued-row"><button class="intel-player-line" data-intel-player="${esc(x.player.id)}"><span>${playerPhoto(x.player,'intel-mini-photo')}<span><strong>${esc(x.player.name)}</strong><small>€ ${fmt(x.player.price)} mln · ${fmt(x.player.expectedPoints)} xP · ${fmt(x.player.ownership)}% gekozen${x.context?` · ${esc(x.context)}`:''}</small></span></span><b>${fmt(x.score,0)}/100</b></button>${x.alternative?`<button class="intel-alternative" data-intel-player="${esc(x.alternative.id)}">Alternatief: ${esc(x.alternative.name)} · € ${fmt(x.alternative.price)} mln · ${fmt(x.alternative.expectedPoints)} xP</button>`:''}</article>`).join('')||'<div class="intel-empty">Geen speler overschrijdt de waarschuwingsgrens.</div>'}</div></section>`}
function broadcast(a){const clean=value=>String(value??'').replace(/market[- ]?mismatch/gi,'verschil tussen verwachting en populariteit').replace(/marktbreed buy window/gi,'interessant koopmoment').replace(/canonical posities/gi,'geldige posities').replace(/confidence/gi,'zekerheid'),label=value=>({'FIXTURE STORY':'SCHEMA','MINUTES WATCH':'MINUTEN','MARKET MISMATCH':'MARKTWAARDE'}[value]||value);return `<section class="broadcast-hero panel"><span class="eyebrow">FVT Weekbriefing</span><h2>Uitzending in één minuut</h2><p>De sterkste, verschillende dataverhalen voor speelronde ${a.startRound}.</p></section><section class="broadcast-grid">${a.editorialStories.map(i=>`<article class="broadcast-card"><span>🎙 ${esc(label(i.editorialLabel))}</span><h3>${esc(clean(i.title))}</h3><dl><dt>Wat?</dt><dd>${esc(clean(i.conclusion))}</dd><dt>Waarom?</dt><dd>${esc(clean(i.why))}</dd><dt>Fantasy</dt><dd>${esc(clean(i.fantasy))}</dd></dl><footer><b>${esc(i.confidence.level)} zekerheid${i.composite?` · ${i.sourceSignals.length} signalen`:''}</b><button data-copy-insight="${esc(i.id)}">Kopieer aandachtspunt</button></footer></article>`).join('')||'<div class="intel-empty">Nog onvoldoende verschillende sterke aandachtspunten.</div>'}</section>`}
function topmanagers(){const rows=selectEliteView(getElitePlayerStats(),{season:state.season,cohort:state.cohort}),profiles=new Map(getPlayerProfiles().map(p=>[String(p.id),p])),round=rows[0]?.gameweek,coverage=rows[0]?.coverage;if(!rows.length)return `<section class="panel elite-empty"><span class="eyebrow">Topmanagers</span><h2>Nog geen gepubliceerde Topmanager-data</h2><p>Publiceer ELITE_PLAYER_STATS en vul de bijbehorende GID in. Algemene marktdata wordt nooit als gelockte managerdata gepresenteerd.</p></section>`;const enriched=rows.map(row=>({row,player:profiles.get(String(row.playerId))}));const rowHtml=({row,player})=>`<tr><td><button class="elite-player" data-intel-player="${esc(row.playerId)}">${playerPhoto(player||{},'intel-mini-photo')}<span><b>${esc(player?.name||row.playerId)}</b><small>${esc(player?.club||'Niet gekoppeld')}</small></span></button></td><td>${formatEliteMetric(row.selected,row.validTeams)}</td><td>${formatEliteMetric(row.starter,row.validTeams)}</td><td>${formatEliteMetric(row.bench,row.validTeams)}</td><td>${formatEliteMetric(row.captain,row.validTeams)}</td><td>${formatEliteMetric(row.vice,row.validTeams)}</td><td class="${(row.eliteGapPercentagePoints??0)>=0?'up':'down'}">${row.eliteGapPercentagePoints===null?'—':`${row.eliteGapPercentagePoints>0?'+':''}${fmt(row.eliteGapPercentagePoints)} pp`}</td></tr>`;const cards=(title,list,value)=>`<article class="panel"><span class="eyebrow">${title}</span>${list.map(x=>`<button class="intel-player-line" data-intel-player="${esc(x.row.playerId)}"><span>${playerPhoto(x.player||{},'intel-mini-photo')}<span><strong>${esc(x.player?.name||x.row.playerId)}</strong><small>${esc(x.player?.club||'Niet gekoppeld')} · deadline SR${round}</small></span></span><b>${value(x)}</b></button>`).join('')||'<div class="intel-empty">Geen betrouwbaar signaal.</div>'}</article>`;const consensus=enriched.slice(0,5),differentials=[...enriched].filter(x=>x.row.marketSelectedPercentage!==null&&x.row.eliteGapPercentagePoints>=10).sort((a,b)=>b.row.eliteGapPercentagePoints-a.row.eliteGapPercentagePoints).slice(0,5),captains=[...enriched].sort((a,b)=>(b.row.captain.percentage??-1)-(a.row.captain.percentage??-1)).slice(0,5);return `<section class="intel-hero panel elite-hero"><div><span class="eyebrow">Elite Manager Intelligence</span><h2>Topmanagers · deadline SR${round}</h2><p>Publiek beschikbare, gelockte opstellingen. Geen voorspelling van toekomstige managerkeuzes.</p></div><div class="intel-live">${metric('Cohort',`Top ${state.cohort}`)}${metric('Teams verwerkt',`${coverage.validTeams} / ${coverage.requestedTeams}`)}${metric('Dekking',`${fmt(coverage.percentage)}%`)}${metric('Betrouwbaarheid',coverage.level)}</div></section><section class="intel-grid three">${cards('Elite consensus',consensus,x=>`${fmt(x.row.selected.percentage)}%`)}${cards('Elite differentials',differentials,x=>`+${fmt(x.row.eliteGapPercentagePoints)} pp`)}${cards('Captain consensus',captains,x=>formatEliteMetric(x.row.captain,x.row.validTeams))}</section><section class="panel intel-table elite-table"><span class="eyebrow">Keuzes bij deadline SR${round} ${info('Coverage','Het aantal succesvol verwerkte teams ten opzichte van het aangevraagde cohort. Percentages gebruiken alleen geldige teams.')}</span><h3>Spelers binnen Top ${state.cohort}</h3><div class="elite-table-scroll"><table><thead><tr><th>Speler</th><th>Gekozen</th><th>Basis</th><th>Bank</th><th>Captain</th><th>Vice-captain</th><th>Verschil met markt</th></tr></thead><tbody>${enriched.map(rowHtml).join('')}</tbody></table></div></section>`}
const eliteSortDefinitions={selectedCount:r=>r.selected.count,selectedPct:r=>r.selected.percentage,starterCount:r=>r.starter.count,starterPct:r=>r.starter.percentage,benchCount:r=>r.bench.count,benchPct:r=>r.bench.percentage,captainCount:r=>r.captain.count,captainPct:r=>r.captain.percentage,viceCount:r=>r.vice.count,vicePct:r=>r.vice.percentage,gap:r=>r.eliteGapPercentagePoints,bought:r=>r.bought?.count, sold:r=>r.sold?.count,net:r=>r.netTransfers,template:r=>r.templateScore}
