function eliteStructureRecap(){if(state.eliteView!=='recap')return'';const formationRows=getEliteFormations().filter(row=>row.season===state.season&&Number(row.cohort)===Number(state.cohort)),round=Math.max(0,...formationRows.map(row=>row.gameweek)),formations=eliteNumericSort(formationRows.filter(row=>row.gameweek===round),row=>row.percentage).slice(0,6),clubs=eliteNumericSort(getEliteClubExposure().filter(row=>row.season===state.season&&row.gameweek===round&&Number(row.cohort)===Number(state.cohort)),row=>row.averageSquadPlayers).slice(0,8);if(!formations.length&&!clubs.length)return'';return `<section class="intel-grid two elite-structure-recap"><article class="panel"><span class="eyebrow">Formaties · deadline SR${round}</span>${formations.map(row=>`<div class="club-rank"><span><b>${esc(row.formation)}</b></span><strong>${row.count} / ${row.validTeams} · ${fmt(row.percentage)}%</strong></div>`).join('')||'<div class="intel-empty">Geen volledig valide basiselftal.</div>'}</article><article class="panel"><span class="eyebrow">Club exposure · selectie SR${round}</span>${clubs.map(row=>`<div class="club-rank">${clubLogo(row.club)}<span>${esc(row.club)}<small>Gem. ${fmt(row.averageSquadPlayers)} spelers · ${fmt(row.averageStarters)} in basis</small></span><strong>${row.teamsWith2.count} / ${row.validTeams} ≥2</strong></div>`).join('')||'<div class="intel-empty">Geen betrouwbare clubkoppeling.</div>'}</article></section>`}
function renderEliteRoundRecapLegacy(roundWindow){const available=roundWindow.map(item=>item.round);if(!available.length)return topmanagers();if(!available.includes(Number(state.eliteRound)))state.eliteRound=available.at(-1);const selected=roundWindow.find(item=>item.round===Number(state.eliteRound)),round=selected.round,rows=selectEliteView(getElitePlayerStats(),{season:state.season,gameweek:round,cohort:state.cohort}),profiles=new Map(getPlayerProfiles().map(player=>[String(player.id),player])),coverage=rows[0]?.coverage,chips=getChipUsage().filter(row=>row.season===state.season&&row.round===round),groups=['#1','Top 10','Top 100','Top 1000','Hele spel'],chipCodes=[...new Set(chips.map(row=>row.chipCode))],sorted=eliteNumericSort(rows,eliteSortDefinitions[state.eliteSort]||eliteSortDefinitions.starterPct,state.eliteDirection),formations=eliteNumericSort(getEliteFormations().filter(row=>row.season===state.season&&row.gameweek===round&&Number(row.cohort)===Number(state.cohort)),row=>row.percentage).slice(0,6),clubs=eliteNumericSort(getEliteClubExposure().filter(row=>row.season===state.season&&row.gameweek===round&&Number(row.cohort)===Number(state.cohort)),row=>row.averageSquadPlayers).slice(0,8);return `<section class="intel-hero panel elite-hero"><div><span class="eyebrow">Terugblik Topmanagers</span><h2>SR${round} · ${selected.status}</h2><p>De deadline is geweest en managerkeuzes zijn publiek.${selected.status==='Lopend'?' De speelronde loopt nog; globale chipaantallen kunnen wijzigen.':''}</p></div><div class="intel-live">${metric('Cohort',`Top ${state.cohort}`)}${metric('Teams verwerkt',coverage?`${coverage.validTeams} / ${coverage.requestedTeams}`:'—')}${metric('Status',selected.status)}</div></section><nav class="elite-subtabs"><button data-elite-view="market">Markt & transfers</button><button data-elite-view="recap" class="active">Terugblik</button></nav><nav class="elite-round-tabs">${roundWindow.map(item=>`<button data-elite-round="${item.round}" class="${item.round===round?'active':''}">SR${item.round} · ${item.status}</button>`).join('')}</nav><section class="panel intel-table elite-table"><span class="eyebrow">Locked opstelling SR${round}</span><div class="elite-table-scroll"><table><thead><tr><th>Speler</th><th>${eliteSortButton('starterPct','Basis')}</th><th>${eliteSortButton('benchPct','Bank')}</th><th>${eliteSortButton('captainPct','Captain')}</th><th>${eliteSortButton('vicePct','Vice')}</th></tr></thead><tbody>${sorted.map(row=>`<tr><td>${esc(profiles.get(String(row.playerId))?.name||row.playerId)}</td><td>${formatEliteMetric(row.starter,row.validTeams)}</td><td>${formatEliteMetric(row.bench,row.validTeams)}</td><td>${formatEliteMetric(row.captain,row.validTeams)}</td><td>${formatEliteMetric(row.vice,row.validTeams)}</td></tr>`).join('')}</tbody></table></div></section><section class="panel intel-table elite-chip-table"><span class="eyebrow">Chipgebruik SR${round} · ${selected.status}</span>${chips.length?`<div class="elite-table-scroll"><table><thead><tr><th>Chip</th>${groups.map(group=>`<th>${group}</th>`).join('')}</tr></thead><tbody>${chipCodes.map(code=>`<tr><th>${esc(chips.find(row=>row.chipCode===code)?.chip||code)}</th>${groups.map(group=>{const item=chips.find(row=>row.chipCode===code&&row.group===group);return`<td>${item?(item.percentage===null?`${item.count} · % —`:`${item.count} / ${item.managers} · ${fmt(item.percentage)}%`):'—'}</td>`}).join('')}</tr>`).join('')}</tbody></table></div>`:'<div class="intel-empty">Voor deze ronde zijn nog geen gepubliceerde chipregels beschikbaar.</div>'}</section><section class="intel-grid two elite-structure-recap"><article class="panel"><span class="eyebrow">Formaties · SR${round}</span>${formations.map(row=>`<div class="club-rank"><span><b>${esc(row.formation)}</b></span><strong>${row.count} / ${row.validTeams} · ${fmt(row.percentage)}%</strong></div>`).join('')||'<div class="intel-empty">Nog geen geaggregeerde formaties.</div>'}</article><article class="panel"><span class="eyebrow">Club exposure · SR${round}</span>${clubs.map(row=>`<div class="club-rank">${clubLogo(row.club)}<span>${esc(row.club)}<small>Gem. ${fmt(row.averageSquadPlayers)} selectie · ${fmt(row.averageStarters)} basis</small></span><strong>${row.teamsWith1.count} ≥1 · ${row.teamsWith2.count} ≥2 · ${row.teamsWith3.count} ≥3</strong></div>`).join('')||'<div class="intel-empty">Nog geen geaggregeerde club exposure.</div>'}</article></section>`}
function renderEliteChipUsage(round, status){const chips=getChipUsage().filter(row=>row.season===state.season&&row.round===round),groups=['#1','Top 10','Top 100','Top 1000','Hele spel'],codes=[...new Set(chips.map(row=>row.chipCode))];return `<section class="panel intel-table elite-chip-table"><span class="eyebrow">Chipgebruik SR${round} · ${status}</span>${chips.length?`<div class="elite-table-scroll"><table><thead><tr><th>Chip</th>${groups.map(group=>`<th>${group}</th>`).join('')}</tr></thead><tbody>${codes.map(code=>`<tr><th>${esc(chips.find(row=>row.chipCode===code)?.chip||code)}</th>${groups.map(group=>{const item=chips.find(row=>row.chipCode===code&&row.group===group);return`<td>${item?(item.percentage===null?`${item.count} · % —`:`${item.count} / ${item.managers} · ${fmt(item.percentage)}%`):'—'}</td>`}).join('')}</tr>`).join('')}</tbody></table></div>`:'<div class="intel-empty">Voor deze ronde zijn nog geen gepubliceerde chipregels beschikbaar.</div>'}</section>`}
function renderEliteRoundRecap(roundWindow){
  const available=roundWindow.map(item=>item.round)
  if(!available.length)return topmanagers()
  if(!available.includes(Number(state.eliteRound)))state.eliteRound=available.at(-1)
  const selected=roundWindow.find(item=>item.round===Number(state.eliteRound)),round=selected.round
  const rows=selectEliteView(getElitePlayerStats(),{season:state.season,gameweek:round,cohort:state.cohort})
  const profiles=new Map(getPlayerProfiles().map(player=>[String(player.id),player]))
  const coverage=rows[0]?.coverage
  const sorted=eliteNumericSort(rows,eliteSortDefinitions[state.eliteSort]||eliteSortDefinitions.starterPct,state.eliteDirection)
  const filtered=filterEliteLineupRows(sorted,profiles,state.eliteSearch,state.eliteClub)
  const clubs=[...new Set(rows.map(row=>profiles.get(String(row.playerId))?.club).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'nl'))
  const exposure=eliteNumericSort(getEliteClubExposure().filter(row=>row.season===state.season&&row.gameweek===round&&Number(row.cohort)===Number(state.cohort)),row=>row.averageSquadPlayers).slice(0,8)
  const formations=eliteNumericSort(getEliteFormations().filter(row=>row.season===state.season&&row.gameweek===round&&Number(row.cohort)===Number(state.cohort)),row=>row.percentage).slice(0,6)
  return `<section class="intel-hero panel elite-hero"><div><span class="eyebrow">Terugblik Topmanagers</span><h2>SR${round} · ${selected.status}</h2><p>De deadline is geweest en managerkeuzes zijn publiek.</p></div><div class="intel-live">${metric('Cohort',`Top ${state.cohort}`)}${metric('Teams verwerkt',coverage?`${coverage.validTeams} / ${coverage.requestedTeams}`:'—')}${metric('Status',selected.status)}</div></section><nav class="elite-subtabs"><button data-elite-view="market">Markt & transfers</button><button data-elite-view="recap" class="active">Terugblik</button></nav><nav class="elite-round-tabs">${roundWindow.map(item=>`<button data-elite-round="${item.round}" class="${item.round===round?'active':''}">SR${item.round} · ${item.status}</button>`).join('')}</nav><section class="panel intel-table elite-table"><span class="eyebrow">Locked opstelling SR${round}</span><div class="elite-lineup-filters"><input data-elite-search type="search" value="${esc(state.eliteSearch)}" placeholder="Zoek speler…" aria-label="Zoek speler"><select data-elite-club aria-label="Filter op club"><option value="">Alle clubs</option>${clubs.map(club=>`<option value="${esc(club)}" ${state.eliteClub===club?'selected':''}>${esc(club)}</option>`).join('')}</select><button type="button" data-elite-reset>Reset</button><small>${filtered.length} spelers</small></div><div class="elite-table-scroll"><table><thead><tr><th>Speler</th><th>${eliteSortButton('starterPct','Basis')}</th><th>${eliteSortButton('benchPct','Bank')}</th><th>${eliteSortButton('captainPct','Captain')}</th><th>${eliteSortButton('vicePct','Vice')}</th></tr></thead><tbody>${filtered.map(row=>{const player=profiles.get(String(row.playerId));return`<tr><td><button class="elite-player" data-intel-player="${esc(row.playerId)}">${playerPhoto(player||{},'intel-mini-photo')}<span><b>${esc(player?.name||row.playerId)}</b><small>${esc(player?.club||'Niet gekoppeld')}</small></span></button></td><td>${formatEliteMetric(row.starter,row.validTeams)}</td><td>${formatEliteMetric(row.bench,row.validTeams)}</td><td>${formatEliteMetric(row.captain,row.validTeams)}</td><td>${formatEliteMetric(row.vice,row.validTeams)}</td></tr>`}).join('')||'<tr><td colspan="5"><div class="intel-empty">Geen spelers binnen deze filters.</div></td></tr>'}</tbody></table></div></section>${renderEliteChipUsage(round,selected.status)}<section class="intel-grid two elite-structure-recap"><article class="panel"><span class="eyebrow">Formaties · SR${round}</span>${formations.map(row=>`<div class="club-rank"><span><b>${esc(row.formation)}</b></span><strong>${row.count} / ${row.validTeams} · ${fmt(row.percentage)}%</strong></div>`).join('')}</article><article class="panel"><span class="eyebrow">Club Exposure · SR${round} ${info('Club Exposure','Club Exposure laat zien hoeveel spelers van een club voorkomen bij de onderzochte topmanagers. Je ziet het gemiddelde aantal spelers in selectie en basis en hoeveel managers minimaal 1, 2 of 3 spelers van die club bezitten.')}</span><div class="elite-exposure-list">${exposure.map(row=>`<div class="elite-exposure-row"><span>${clubLogo(row.club)}<b>${esc(row.club)}</b><small>Gem. ${fmt(row.averageSquadPlayers)} selectie · ${fmt(row.averageStarters)} basis</small></span><strong><i>1+ spelers: ${row.teamsWith1.count}</i><i>2+ spelers: ${row.teamsWith2.count}</i><i>3+ spelers: ${row.teamsWith3.count}</i></strong></div>`).join('')||'<div class="intel-empty">Nog geen geaggregeerde club exposure.</div>'}</div></article></section>`
}
function topmanagersComplete(){const roundWindow=getAvailableLockedEliteRounds(getElitePlayerStats(),{season:state.season,chipUsage:getChipUsage(),limit:2});if(state.eliteView==='recap')return renderEliteRoundRecap(roundWindow);return topmanagersFinal()}
function content(a){ return ({overview:overviewFinal,topmanagers:topmanagersComplete,clubs,players:playersFinal,market,fixtures:fixturesTarget,opponents:opponentsFinal,budget:budgetFinal,positions,trends,radar,overvalued,broadcast:broadcastFinal}[state.tab]||overviewFinal)(a) }
function drawer(a){ if(state.insightId){const i=[...a.editorialStories,...a.insights].find(x=>x.id===state.insightId);if(!i)return'';return `<div class="intel-backdrop" data-intel-close></div><aside class="intel-drawer"><header><span>Intelligence detail</span><button data-intel-close>×</button></header><div><span class="eyebrow">${esc(i.category)}</span><h2>${esc(i.title)}</h2><h4>Waarom dit telt</h4><p>${esc(i.why)}</p><h4>Fantasy-impact</h4><p>${esc(i.fantasy)}</p><h4>Data</h4><div class="talking-evidence">${Object.entries(i.metrics).map(([k,v])=>metric(k,fmt(v))).join('')}</div>${i.composite?`<h4>Onderliggende signalen</h4><p>${i.sourceSignals.map(x=>esc(x.category)).join(' · ')}</p>`:''}<h4>Confidence</h4><p>${esc(i.confidence.level)} · ${fmt(i.confidence.score,0)}/100</p>${i.entityId?`<button class="intel-primary" data-intel-player="${esc(i.entityId)}">Bekijk volledig spelersprofiel</button>`:''}</div></aside>`} if(!state.playerId)return'';const p=getPlayerDetailProfile({playerId:state.playerId,season:state.season});return p?`<div class="intel-backdrop" data-intel-close></div><aside class="intel-drawer"><header><span>Spelerprofiel</span><button data-intel-close>×</button></header><div>${renderPlayerDetailProfile(p,state.playerTab,{startRound:state.round,count:5,selectedFixtureId:null})}</div></aside>`:'' }
export function createAnalysisScreen(){const rounds=ensure(),a=buildAnalysis({season:state.season,startRound:state.round,horizon:state.horizon});const seasons=[...new Set(getFixtures().map(f=>f.season).filter(Boolean))];return `<section class="intelligence-suite"><section class="intel-toolbar panel"><div><span class="eyebrow">FVT Intelligence</span><h2>Analyse</h2></div><div>${filter('Seizoen','season',seasons,state.season)}${filter('Startronde','round',rounds,state.round,v=>`SR${v}`)}${filter('Horizon','horizon',[1,3,5],state.horizon,v=>`${v} ronde${v===1?'':'s'}`)}${state.tab==='topmanagers'?filter('Cohort','cohort',ELITE_COHORTS,state.cohort,v=>`Top ${v}`):''}</div></section><nav class="intel-tabs">${tabs.map(([id,label])=>`<button data-analysis-tab="${id}" class="${state.tab===id?'active':''}">${label}</button>`).join('')}</nav><div class="intel-content">${content(a)}</div>${drawerFinal(a)}</section>`}
function filter(label,key,values,current,format=v=>v){return `<label><span>${label}</span><select data-analysis-filter="${key}">${values.map(v=>`<option value="${esc(v)}" ${String(v)===String(current)?'selected':''}>${esc(format(v))}</option>`).join('')}</select></label>`}
function fixturesFinal(a){const swings=a.structuralFixtures.filter(x=>x.structuralSwing!==null),upcoming=a.structuralFixtures.flatMap(c=>(c.upcomingSwings||[]).map(s=>({...s,club:c.club}))).sort((x,y)=>x.startRound-y.startRound||Math.abs(y.delta)-Math.abs(x.delta)||x.club.localeCompare(y.club,'nl')),strength=n=>Math.abs(n)>=25?'Sterk':Math.abs(n)>=18?'Duidelijk':'Licht',rows=list=>list.slice(0,5).map(c=>`<div class="fixture-rank"><span>${clubLogo(c.club)} ${esc(c.club)}</span><small>${fmt(c.previousAverage,0)} → ${fmt(c.nextAverage,0)} · ${strength(c.structuralSwing)} · ${esc(c.confidence.level)}</small><b class="${c.structuralSwing>=0?'up':'down'}">${c.structuralSwing>=0?'+':''}${fmt(c.structuralSwing,0)}</b></div>`).join(''),early=a.startRound<=3&&swings.length===0;return `<section class="intel-grid two"><article class="panel"><span class="eyebrow">Beste schema’s ${info('Schemascore','Kwaliteit van de komende wedstrijden.\nHoger is gunstiger. Vrije rondes tellen niet als nul en dubbele speelrondes tellen volledig mee.')}</span>${[...a.clubs].sort((x,y)=>y.fixture-x.fixture).slice(0,8).map(c=>`<div class="fixture-rank">${clubLogo(c.club)}<span>${esc(c.club)}</span>${scoreBar(c.fixture)}<b>${fmt(c.fixture,0)}</b></div>`).join('')}</article><article class="panel"><span class="eyebrow">Huidige schema-omslag ${info('Huidige schema-omslag','Vergelijkt maximaal vijf eerdere met vijf komende wedstrijden.\nMinimaal drie eerdere en vier komende wedstrijden zijn nodig.\nEén extreme wedstrijd is niet genoeg voor een structureel signaal.')}</span><small>Vorige vijf wedstrijden tegenover komende vijf</small><h4>Schema wordt duidelijk makkelijker</h4>${rows(swings.filter(c=>c.structuralSwing>0))||(early?'<div class="intel-empty">Nog te vroeg voor deze vergelijking. Minimaal drie eerdere wedstrijden zijn nodig.</div>':'<div class="intel-empty">Geen duidelijke versoepeling van het schema.</div>')}<h4>Schema wordt duidelijk moeilijker</h4>${rows(swings.filter(c=>c.structuralSwing<0))||(early?'<div class="intel-empty">Nog te vroeg voor deze vergelijking.</div>':'<div class="intel-empty">Geen duidelijke verzwaring van het schema.</div>')}</article></section>${upcoming.length?`<section class="panel"><span class="eyebrow">Toekomstige omslagpunten</span>${upcoming.slice(0,8).map(c=>`<div class="fixture-rank"><span>${clubLogo(c.club)} ${esc(c.club)}<small>Vanaf SR${c.startRound} · ${fmt(c.beforeAverage,0)} → ${fmt(c.afterAverage,0)} · ${strength(c.delta)}</small></span><b class="${c.delta>0?'up':'down'}">${c.delta>0?'+':''}${fmt(c.delta,0)}</b></div>`).join('')}</section>`:''}`}
function opponentsFinal(a){const positions=['keeper','verdediger','middenvelder','aanvaller'],top=pos=>[...a.opponentStats].filter(o=>o.positions[pos].pointsPer90!==null).sort((x,y)=>y.positions[pos].pointsPer90-x.positions[pos].pointsPer90||y.positions[pos].matches-x.positions[pos].matches).slice(0,3),explanation='De score gebruikt Fantasy-punten per 90 die spelers tegen deze club behaalden.\nHoger betekent dat de tegenstander historisch meer punten toestaat.\nBetrouwbaarheid kijkt vooral naar onafhankelijke wedstrijden; spelerwaarnemingen tellen aanvullend mee.\n1 wedstrijd is laag, 2–4 middel, 5–8 behoorlijk en 9+ hoog.';return `<section class="intel-grid four opponent-top">${positions.map(pos=>`<article class="panel"><span class="eyebrow">Top 3 · ${positionLabel(pos)}</span>${top(pos).map(o=>{const d=o.positions[pos];return `<div class="club-rank" title="${d.matches} wedstrijd(en) · ${d.observations} spelerwaarnemingen"><span>${clubLogo(o.opponent)} ${esc(o.opponent)}<small>${d.matches} wedstrijd(en)</small></span><b>${fmt(d.pointsPer90)} <i class="confidence ${d.confidence}">${esc(d.confidence)}</i></b></div>`}).join('')||'<div class="intel-empty">Nog geen geldige waarnemingen.</div>'}</article>`).join('')}</section><section class="panel intel-table"><span class="eyebrow">Toegestane punten per 90 ${info('Tegenstanderdata',explanation)}</span><h3>Tegen welke clubs worden de meeste fantasypunten gehaald?</h3><table><thead><tr><th>#</th><th>Tegenstander</th><th>Wedstrijden</th><th>Spelerwaarnemingen</th><th>Punten/90</th>${positions.map(p=>`<th>${positionLabel(p)}</th>`).join('')}<th>Zekerheid</th></tr></thead><tbody>${a.opponentStats.map((o,i)=>`<tr><td>${i+1}</td><td>${clubLogo(o.opponent)} ${esc(o.opponent)}</td><td>${o.matches}</td><td>${o.observations}</td><td><b>${fmt(o.pointsPer90)}</b></td>${positions.map(p=>{const d=o.positions[p];return `<td title="${d.pointsPer90===null?esc(d.missingReason):`${d.matches} wedstrijd(en) · ${d.observations} spelerwaarnemingen`}">${fmt(d.pointsPer90)}${d.pointsPer90===null?'':` <span class="confidence ${d.confidence}">${esc(d.confidence)}</span>`}</td>`}).join('')}<td><span class="confidence ${o.confidence}">${esc(o.confidence)}</span></td></tr>`).join('')}</tbody></table>${a.opponentStats.length?'':'<div class="intel-empty">Nog geen geldige wedstrijdhistorie voor deze analyse.</div>'}</section>`}
function fixturesTarget(a){const html=fixturesFinal(a),insufficient=a.startRound<=3&&!a.structuralFixtures.some(x=>x.structuralSwing!==null);return insufficient?html.replace(/<h4>Schema wordt duidelijk makkelijker[\s\S]*?<\/article>/,`<div class="intel-empty"><strong>Nog te vroeg voor een huidige schema-omslag</strong><p>Voor een betrouwbare vergelijking zijn minimaal drie eerdere wedstrijden nodig. Zodra er genoeg data is, vergelijken we het recente schema met de komende wedstrijden.</p></div></article>`):html}
function overviewFinal(a){return overview(a).replaceAll('Projectie tegenover populariteit','Verwachte punten tegenover populariteit').replaceAll('projectiepercentiel','niveau van verwachte punten').replaceAll('ownershippercentiel','populariteitsniveau')}
function playersFinal(a){return players(a).replace('title="Sterkte van de gemeten verandering; geen kanspercentage"','aria-label="Sterkte van de gemeten verandering; geen kanspercentage"')}
function budgetFinal(a){return budget(a).replaceAll('projectie','verwachte punten').replaceAll('Projectie','Verwachte punten').replaceAll('sweet spot','beste prijsklasse').replaceAll('title="Kleine steekproef"','aria-label="Kleine steekproef"')}
function drawerFinal(a){return drawer(a).replaceAll('Intelligence detail','Uitleg bij signaal').replaceAll('Confidence','Zekerheid').replaceAll('previous5','Vorige 5').replaceAll('next5','Komende 5').replaceAll('following5','Daarna 5').replaceAll('swing','Verschil').replaceAll('sample','Steekproef').replaceAll('qualityPercentile','Niveau verwachte punten').replaceAll('ownershipPercentile','Niveau populariteit').replaceAll('fixture','Schema')}
function broadcastFinal(a){return broadcast(a).replaceAll('BIG STORY','GROOT VERHAAL').replaceAll('CAUTION','PAS OP').replaceAll('FIXTURE STORY','SCHEMA').replaceAll('UNDER THE RADAR','ONDER DE RADAR').replaceAll('STAT OF THE WEEK','STAT VAN DE WEEK').replaceAll('MINUTES WATCH','MINUTEN').replace(/5 vs 5 geldige wedstrijden/gi,'vijf eerdere en vijf komende wedstrijden').replace(/marktbrede tegenstandertrend/gi,'opvallende tegenstandertrend').replace(/projectiepercentiel/gi,'niveau van verwachte punten').replace(/ownershippercentiel/gi,'populariteitsniveau').replace(/ownership/gi,'populariteit').replace(/fixture/gi,'wedstrijd').replace(/confidence/gi,'zekerheid')}
document.addEventListener('click',event=>{const view=event.target.closest('[data-elite-view]');if(view){state.eliteView=view.dataset.eliteView;rerender();return}const sort=event.target.closest('[data-elite-sort]');if(sort){const key=sort.dataset.eliteSort;state.eliteDirection=state.eliteSort===key&&state.eliteDirection==='desc'?'asc':'desc';state.eliteSort=key;rerender()}})
document.addEventListener('click',event=>{const round=event.target.closest('[data-elite-round]');if(round){state.eliteRound=Number(round.dataset.eliteRound);rerender()}})
document.addEventListener('input',event=>{if(event.target.matches('[data-elite-search]')){state.eliteSearch=event.target.value;const cursor=event.target.selectionStart;rerender();const input=document.querySelector('[data-elite-search]');if(input){input.focus();input.setSelectionRange(cursor,cursor)}}})
document.addEventListener('change',event=>{if(event.target.matches('[data-elite-club]')){state.eliteClub=event.target.value;rerender()}})
document.addEventListener('click',event=>{if(event.target.closest('[data-elite-reset]')){state.eliteSearch='';state.eliteClub='';rerender()}})
function rerender(){const root=document.querySelector('#page-content');if(root){root.innerHTML=safeHtml(createAnalysisScreen());mountAnalysisScreen()}}
export function mountAnalysisScreen(){document.querySelectorAll('[data-analysis-tab]').forEach(x=>x.addEventListener('click',()=>{state.tab=x.dataset.analysisTab;rerender()}));document.querySelectorAll('[data-radar-toggle]').forEach(x=>x.addEventListener('click',()=>{state.radarExpanded=!state.radarExpanded;rerender()}));document.querySelectorAll('[data-analysis-filter]').forEach(x=>x.addEventListener('change',()=>{const key=x.dataset.analysisFilter;state[key]=['round','horizon'].includes(key)?Number(x.value):x.value;if(key==='season')state.round=0;rerender()}));document.querySelectorAll('[data-intel-player]').forEach(x=>x.addEventListener('click',e=>{e.stopPropagation();state.insightId='';state.playerId=x.dataset.intelPlayer;rerender()}));document.querySelectorAll('[data-intel-insight]').forEach(x=>x.addEventListener('click',()=>{state.insightId=x.dataset.intelInsight;rerender()}));document.querySelectorAll('[data-intel-close]').forEach(x=>x.addEventListener('click',()=>{state.playerId='';state.insightId='';rerender()}));document.querySelectorAll('.intel-drawer [data-player-detail-tab]').forEach(x=>x.addEventListener('click',()=>{state.playerTab=x.dataset.playerDetailTab;rerender()}));document.querySelectorAll('[data-copy-insight]').forEach(x=>x.addEventListener('click',async()=>{const a=buildAnalysis({season:state.season,startRound:state.round,horizon:state.horizon}),i=[...a.editorialStories,...a.insights].find(y=>y.id===x.dataset.copyInsight);if(i){try{await navigator.clipboard.writeText(`${i.title}\n\nWat? ${i.conclusion}\nWaarom? ${i.why}\nFantasy: ${i.fantasy}\nZekerheid: ${i.confidence.level}`);x.textContent='Gekopieerd ✓'}catch{x.textContent='Kopiëren niet toegestaan'}}}))}
